<script>
  import Checkbox from './Checkbox.svelte'

  import { init } from '../../utils'

  let {
    legend: legendProp = '',
    legendClass: legendClassProp = '',
    label = '',
    labelClass = '',
    items = $bindable([]),
    checkboxes = $bindable([]),
    ref = $bindable(null),
    checked = false,
    class: klass = '',
    checkboxesClass = '',
    disabled = null,
    readonly = null,
    alwaysSend = null,
    ...rest
  } = $props()

  let legend = $state('')
  let legendClass = $state('')

  init(() => {
    legend = legendProp
    legendClass = legendClassProp

    // Let users use either items or checkboxes
    if (checkboxes.length) items = checkboxes
    if (!items.length && !checkboxes.length) {
      console.warn('No checkboxes or items provided to <Checkboxes />')
    }

    // Let users use either label or legend
    if (label) legend = label
    if (labelClass) legendClass = labelClass

    items = items.map(checkbox => {
      if (typeof checkbox === 'string') checkbox = { name: checkbox }
      return { checked, ref: null, ...checkbox }
    })
  })

  const staticCheckboxProps = $derived({ disabled, readonly, alwaysSend })

  // TODO Later: Indeterminate checkboxes
  // Useful for groups of checkboxes.
  // inputInstance.indeterminate = true
</script>

<fieldset {...rest} bind:this={ref} class="fieldset {klass}">
  {#if legend}
    <legend class="legend {legendClass}">{legend}</legend>
  {/if}

  <div class="checkboxes {checkboxesClass}">
    {#each items as checkbox (checkbox.name)}
      <Checkbox
        {...staticCheckboxProps}
        {...checkbox}
        bind:ref={checkbox.ref}
        bind:checked={checkbox.checked}
      />
    {/each}
  </div>
</fieldset>
